const body = $input.first().json.body || $input.first().json;

const sujet = body.sujet_texte || body.titre || body.message || '';
const notes = body.notes || '';

if (!sujet.trim()) {
  throw new Error('Le champ sujet_texte est requis.');
}

return [{
  json: {
    sujet_texte: sujet.trim(),
    notes: notes.trim()
  }
}];

let content = $input.first().json.message?.content || (Array.isArray($input.first().json.content) ? $input.first().json.content[0].text : $input.first().json.content);

if (typeof content === 'string') {
  content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  content = JSON.parse(content);
}

// Retirer le hook du debut du corps s'il est duplique
if (content.corps && content.hook && content.corps.trim().startsWith(content.hook.trim())) {
  content.corps = content.corps.trim().slice(content.hook.trim().length).trim();
}

// Supprimer les asterisques qui auraient pu etre generes
const removeAsterisks = (text) => text ? text.replace(/\*+/g, '') : text;
content.hook = removeAsterisks(content.hook);
content.corps = removeAsterisks(content.corps);
content.cta = removeAsterisks(content.cta);

return [{
  json: {
    ...content,
    date_generation: new Date().toISOString(),
    statut: 'a_valider',
    score_ia: 0,
    suggestions_ia: ''
  }
}];

